appearances.css:
.sk{gap:5px}
.bar button{padding:4px 7px;font-size:10px}
.kb{height:54px}
.models{gap:3px}
.models{flex-wrap:nowrap}
.models button{padding:4px 2px;font-size:8px;letter-spacing:0;flex:1 1 auto;white-space:nowrap}
.ctrls{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0 2px;border:1px solid var(--ln);border-radius:3px;padding:4px 3px 3px}
.ctl{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;gap:0;align-content:start}
.ctl .tr{order:1;width:26px;justify-self:center}
.ctl .tr .kn{width:26px!important;height:26px!important;justify-self:center!important}
.ctl .tr .kn svg{width:100%;height:100%}
.ctl output{order:2;text-align:center;font-size:9px;line-height:1.2;white-space:nowrap}
.ctl .nm{order:3;text-align:center;font-size:7.5px;letter-spacing:.02em;text-transform:none;max-width:100%}
.row{gap:4px 8px}
.row button{padding:4px 7px;font-size:10px}
.seg button{padding:4px 7px;font-size:10px}
